import {DEFAULTS,stlBuffer,zipStore} from './wall.mjs';
import {clamp} from './core.mjs';
const $=id=>document.getElementById(id),ids=['wallWidth','resolution','threshold','contrast','gap','relief','thickness','sourceZ','emitter','sourceX','sourceY','minWeb','socket','exposure'];
let settings={...DEFAULTS},gray,iw,ih,design,sim,worker,generation=0,timer,view='wall',name='Batman',model,initializing3D,toastTimer;
const inputCanvas=document.createElement('canvas'),wallCanvas=document.createElement('canvas');
const fmt=(n,d=0)=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d});
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function output(id){const input=$(id),out=$(id+'Out');if(out){let value=fmt(+input.value,2);if(['wallWidth','gap','relief','sourceZ','emitter'].includes(id))value+=' мм';if(id==='resolution')value+=' пикс.';if(id==='contrast'||id==='exposure')value+='×';out.value=value;}if(input.type==='range')input.style.setProperty('--pct',100*(+input.value-input.min)/(input.max-input.min)+'%');}
function sync(){for(const id of ids){$(id).value=settings[id];output(id);}$('invert').checked=settings.invert;document.querySelectorAll('[data-style]').forEach(b=>b.classList.toggle('active',b.dataset.style===settings.style));}
function busy(state,label='Проверяем тень по 3D-модели…'){$('busy').hidden=!state;$('busyLabel').textContent=label;$('liveState').classList.toggle('calculating',state);$('liveState').innerHTML=`<i></i> ${state?'Расчёт':'Готово'}`;for(const id of['export','helpExport','downloadSculpture'])$(id).disabled=state||!sim;}
async function loadImage(url,label='Референс'){
  const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('Изображение не читается. Используйте PNG, JPEG или WebP.'));image.src=url;});
  if(image.width/image.height<.35||image.width/image.height>3)throw new Error('Соотношение сторон должно быть от 1:3 до 3:1.');const scale=Math.min(1,720/Math.max(image.width,image.height));iw=Math.round(image.width*scale);ih=Math.round(image.height*scale);inputCanvas.width=iw;inputCanvas.height=ih;
  const ctx=inputCanvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#000';ctx.fillRect(0,0,iw,ih);ctx.drawImage(image,0,0,iw,ih);const rgba=ctx.getImageData(0,0,iw,ih).data;gray=new Float32Array(iw*ih);for(let i=0;i<gray.length;i++)gray[i]=(.2126*rgba[i*4]+.7152*rgba[i*4+1]+.0722*rgba[i*4+2])/255;
  const src=inputCanvas.toDataURL('image/png');$('thumb').src=src;$('referenceImage').src=src;name=label;for(const id of['projectName','imageName','referenceTitle'])$(id).textContent=name;calculate();
}
function calculate(width=240,samples=9){
  clearTimeout(timer);generation++;worker?.terminate();sim=null;busy(true,'Строим фигурную 3D-деталь из референса…');if(!gray)return;
  for(const id of ids){if(!$(id).checkValidity()){fail('Проверьте параметр «'+$(id).parentElement.textContent.trim().split('\n')[0]+'».');return;}}
  timer=setTimeout(()=>{worker=new Worker('wall-worker.mjs',{type:'module'});const id=generation;
    worker.onmessage=({data})=>{if(data.id!==generation)return;if(data.error){fail(data.error);return;}if(data.phase==='geometry'){design=data.d;updateDesign();paintCompare();$('busyLabel').textContent='Трассируем лучи через фигуру и стойки…';if(view==='model')void update3D();}else{sim=data.sim;busy(false);paintWall();paintCompare();updateMetrics();if(model){model.dirty=true;if(view==='model')void update3D();}}};
    worker.onerror=e=>fail(e.message);worker.postMessage({id,gray,iw,ih,settings,width,samples});
  },180);
}
function fail(message){sim=null;busy(false);$('liveState').textContent='Проверьте параметры';$('readyChip').textContent='Ошибка';$('readyChip').className='chip warn';$('warningNote').textContent=message;toast(message);}
function updateDesign(){const d=design,p=d.p;const size=d.bounds.map(b=>b[1]-b[0]);$('polarity').textContent=(d.darkBackground?'Тёмный фон. ':'Светлый фон. ')+(p.style==='solid'?'Выделен силуэт: проверьте его во вкладке «Проверка».':'Светлые линии становятся тенью.');$('sizeMetric').textContent=`${fmt(p.wallWidth/10)} × ${fmt(d.height/10)} см`;$('holesMetric').textContent=fmt(d.holes);$('bridgesMetric').textContent=`соединений фрагментов: ${d.bridges}`;$('dimensionLabel').textContent=fmt(p.wallWidth)+' мм · область референса';$('meshLabel').textContent=`Фигура ${fmt(size[0])} × ${fmt(size[1])} × ${fmt(size[2],1)} мм`;
  const large=Math.max(size[0],size[1])>220;$('readyChip').textContent=large?'Проверьте стол':'Единая фигура';$('readyChip').className='chip'+(large?' warn':'');
  const items=[['Фигура связана в одну деталь',false],[`Больших фигурных вырезов: ${d.holes}`,false],[`Добавлено перемычек: ${d.bridges}`,d.bridges>30],['Тени обеих несущих стоек учтены',false],[`Максимальный габарит: ${fmt(Math.max(size[0],size[1]))} мм`,large]];
  $('checks').replaceChildren(...items.map(([text,warn])=>{const li=document.createElement('li');li.textContent=text;if(warn)li.className='warn';return li;}));$('warningNote').textContent=large?'Деталь больше стола 220 мм. Уменьшите картину или разделите её в слайсере.':'Центральная площадка закрывает часть рисунка. Крепёж и патрон подгоняются по реальным деталям.';if(model)model.dirty=true;
}
function updateMetrics(){if(!sim)return;$('iouMetric').textContent=fmt(sim.iou*100,1)+'%';$('blurMetric').textContent=fmt(sim.blur,1)+' мм';$('sampleLabel').textContent=`${sim.samples} выборок · ${fmt(sim.triangles)} треугольников`;$('stageCaption').textContent='Тень рассчитана от геометрии экспортируемой сборки';}
function paintWall(){if(!sim)return;const {width,height,data}=sim;wallCanvas.width=width;wallCanvas.height=height;const ctx=wallCanvas.getContext('2d'),im=ctx.createImageData(width,height);for(let i=0;i<data.length;i++){
  const v=1-Math.exp(-data[i]*settings.exposure*2.8),ambient=settings.ambient;im.data[i*4]=clamp(.065+ambient+v*.90)*255;im.data[i*4+1]=clamp(.075+ambient+Math.pow(v,1.12)*.65)*255;im.data[i*4+2]=clamp(.048+ambient*.7+Math.pow(v,1.3)*.26)*255;im.data[i*4+3]=255;
}ctx.putImageData(im,0,0);const c=$('projectionCanvas');c.width=width*2;c.height=height*2;const out=c.getContext('2d');out.imageSmoothingEnabled=true;out.drawImage(wallCanvas,0,0,c.width,c.height);
  if($('showBody').checked){const sx=c.width/sim.worldWidth,sy=c.height/sim.worldHeight,w=64*sx,h=86*sy,x=(c.width-w)/2,y=(c.height-h)/2;out.fillStyle='#121b17';out.strokeStyle='#777c58';out.lineWidth=1.2;out.beginPath();out.roundRect(x,y,w,h,3);out.fill();out.stroke();out.fillStyle='#b5ad81';out.font=`${Math.max(6,6*sx)}px Segoe UI`;out.textAlign='center';out.fillText('SHADOWFORGE',c.width/2,y+h*.46);out.fillStyle='#686d56';out.font=`${Math.max(5,4.3*sx)}px Segoe UI`;out.fillText('E10 · 3.5 V',c.width/2,y+h*.63);}
  if(model){model.texture.needsUpdate=true;}
}
function paintCompare(){if(!design)return;const d=design;for(const id of['targetCanvas','actualCanvas','errorCanvas']){const c=$(id);c.width=d.nx;c.height=d.ny;const ctx=c.getContext('2d'),im=ctx.createImageData(c.width,c.height);for(let y=0;y<d.ny;y++)for(let x=0;x<d.nx;x++){
    const k=y*d.nx+x,wx=(x+.5-d.nx/2)*d.pitch,wy=(d.ny/2-y-.5)*d.pitch,central=Math.abs(wx)<d.rootW/2+5&&Math.abs(wy)<d.rootH/2+5;let actual=0;if(sim){const ix=Math.floor((wx/sim.worldWidth+.5)*sim.width),iy=Math.floor((.5-wy/sim.worldHeight)*sim.height);actual=sim.shadow[iy*sim.width+ix]||0;}
    let rgb;if(central){const v=((x>>2)+(y>>2))%2?80:95;rgb=[v,v+7,v];}else if(id==='targetCanvas'){const v=d.target[k]?25:225;rgb=[v,v,v-10];}else if(id==='actualCanvas'){const v=(1-actual)*205+20;rgb=[v,v,v-10];}else{const e=Math.abs(actual-d.target[k]);rgb=[30+e*225,35+e*35,30+e*8];}for(let a=0;a<3;a++)im.data[k*4+a]=rgb[a];im.data[k*4+3]=255;
  }ctx.putImageData(im,0,0);}}
async function switchView(next){view=next;for(const b of document.querySelectorAll('[data-view]')){const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));}$('projectionContainer').hidden=view!=='wall';$('modelContainer').hidden=view!=='model';$('compareContainer').hidden=view!=='compare';$('sceneLabel').textContent=view==='model'?'НАСТЕННЫЙ СВЕТИЛЬНИК · РЕАЛЬНЫЕ ДЕТАЛИ':view==='compare'?'ЦЕЛЬ / ТЕНЬ ОТ ОБЪЁМА / ОШИБКА':'КАРТИНА ВОКРУГ СВЕТИЛЬНИКА';if(view==='model')await update3D();}
async function init3D(){const THREE=await import('three'),{OrbitControls}=await import('./vendor/OrbitControls.js'),host=$('modelContainer'),renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.appendChild(renderer.domElement);const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(39,1,1,3000);camera.position.set(250,145,460);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.target.set(0,0,35);controls.minDistance=100;controls.maxDistance=1300;
  scene.add(new THREE.HemisphereLight(0xf8e6bf,0x435345,2.5));const light=new THREE.DirectionalLight(0xffe3b5,3);light.position.set(100,200,300);scene.add(light);const rim=new THREE.DirectionalLight(0xadc7df,2);rim.position.set(-200,-40,120);scene.add(rim);const group=new THREE.Group();scene.add(group);const texture=new THREE.CanvasTexture(wallCanvas);texture.colorSpace=THREE.SRGBColorSpace;model={THREE,renderer,scene,camera,controls,group,texture,dirty:true};new ResizeObserver(()=>{const r=host.getBoundingClientRect();if(r.width&&r.height){renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}}).observe(host);renderer.setAnimationLoop(()=>{if(view==='model'){controls.update();renderer.render(scene,camera);}});
}
async function update3D(){if(!design)return;try{if(!model){initializing3D??=init3D();await initializing3D;}if(!model.dirty)return;const{THREE,group}=model;for(const c of [...group.children]){group.remove(c);c.geometry?.dispose();c.material?.dispose();}const d=design;
  for(const[name,tris,color]of[['sculpture',d.sculpture,0x28302a],['support',d.support,0x68765f],['cover',d.cover,0x17231e],['hardware',d.hardware,0xb5b6a3],['washers',d.washers,0x68765f]]){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(tris.flat(),3));g.computeVertexNormals();const mesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color,roughness:.65,metalness:name==='hardware'?.7:0,side:THREE.DoubleSide}));mesh.name=name;group.add(mesh);}
  const bulb=new THREE.Mesh(new THREE.SphereGeometry(5.5,20,14),new THREE.MeshStandardMaterial({color:0xffdf94,emissive:0xffb347,emissiveIntensity:1.2,transparent:true,opacity:.8}));bulb.name='bulb';bulb.position.set(d.p.sourceX,d.p.sourceY,d.p.sourceZ+2);group.add(bulb);const socket=new THREE.Mesh(new THREE.CylinderGeometry(5,5,10,24),new THREE.MeshStandardMaterial({color:0x9e9c88,metalness:.6,roughness:.4}));socket.rotation.x=Math.PI/2;socket.position.set(0,0,d.p.sourceZ+12);group.add(socket);
  const w=sim?.worldWidth||d.p.wallWidth*1.18,h=sim?.worldHeight||d.height*1.18,wall=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:model.texture,side:THREE.DoubleSide}));wall.name='wall';wall.position.z=-1;group.add(wall);
  for(const [x,y]of[[-d.p.wallWidth*.4,d.height*.4],[d.p.wallWidth*.4,d.height*.4],[-d.p.wallWidth*.4,-d.height*.4],[d.p.wallWidth*.4,-d.height*.4]]){const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(d.p.sourceX,d.p.sourceY,d.p.sourceZ),new THREE.Vector3(x,y,0)]),new THREE.LineBasicMaterial({color:0xd9b77a,transparent:true,opacity:.16}));group.add(line);}model.dirty=false;model.texture.needsUpdate=true;modelOptions();
  }catch(e){toast('3D-просмотр: '+e.message);}}
function modelOptions(){if(!model)return;for(const c of model.group.children){if(c.name==='sculpture')c.position.z=$('explode').checked?25:0;if(c.name==='cover')c.position.z=$('explode').checked?40:0;if(c.name==='wall')c.visible=$('wallVisible').checked;}$('stageCaption').textContent=$('explode').checked?'Детали разнесены для просмотра · тень рассчитана для собранной лампы':'Тень рассчитана от геометрии экспортируемой сборки';}
function save(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1800);}
function printable(tris){let z=Infinity;for(const t of tris)z=Math.min(z,t[2],t[5],t[8]);return tris.map(t=>t.map((v,i)=>i%3===2?v-z:v));}
function project(){return{format:'shadowforge-wall',version:2,name,settings,image:inputCanvas.toDataURL('image/png')};}
function instructions(){const d=design,p=d.p;return `ShadowForge v2 — настенная теневая скульптура\n\nКОНСТРУКЦИЯ\nСтена z=0. Нить E10 в (${p.sourceX}, ${p.sourceY}, ${p.sourceZ}) мм. Фигура начинается на z=${p.gap} мм и имеет рельеф до ${p.relief} мм; толщина ${p.thickness} мм. Передний кожух z=${p.sourceZ+16}..${p.sourceZ+19} мм. Лампа светит НАЗАД, к стене. Чёрные области выбранной цели создаются материалом, светлые — вырезами.\n\nГЕОМЕТРИЯ\nshadow-sculpture.stl — одна связная объёмная фигура с большими контурными вырезами и перемычками.\nwall-base-and-posts.stl — основание 64x86x3 мм с двумя печатными втулками, каналами Ø2.2 мм и буртиками под фигуру на z=${p.gap} мм.\nfront-cover.stl — кожух 64x86x3 мм с посадкой под покупной патрон Ø${p.socket} мм и отверстиями под крепёж стоек.\nСтойки (x,y), мм: ${JSON.stringify(d.posts)}. Наружный диаметр печатных втулок 5 мм, буртики Ø10 мм. Втулки заканчиваются на плоскости фигуры; передний кожух держат две ПОКУПНЫЕ шпильки M2 диаметром 2 мм длиной примерно ${p.sourceZ+24} мм. Их тени включены в расчёт. Шпильки, гайки и шайбы не печатаются и в STL не включены. Центральные зазоры фигуры сделаны больше стоек; допускаются люфт и ручная подгонка.\nГабариты фигуры: ${d.bounds.map(b=>(b[1]-b[0]).toFixed(2)).join(' x ')} мм. Габариты не проверены под ваш принтер.\n\nПЕЧАТЬ И СБОРКА\nКаждая STL отдельно опущена на z=0 для печати. Это не координаты сборки: задняя сторона фигуры при сборке находится в ${p.gap} мм от стены. Основание печатается плоскостью к столу. Буртикам и рельефу могут требоваться поддержки. Подвижную фигуру фиксировать на буртиках гайками и шайбами M2 с наружным диаметром больше её зазоров. Прочность конструкции проверить на образце. Резьба, шпильки M2, гайки и крепёж к стене не включены. Печатные каналы служат заготовкой под крепёж; длину винтов/шпилек и тип фиксации выбрать по фактическим деталям.\nУстановите шпильки M2 через втулки основания. Наденьте фигуру до буртиков и зафиксируйте её шайбами и гайками. Печатайте retaining-washer.stl в ДВУХ экземплярах (Ø12 мм, отверстие Ø2.2 мм, толщина 1.5 мм) и прижмите ими фигуру сверху к буртикам с помощью гаек M2. В основании предусмотрены шестигранные карманы под гайки M2 глубиной 1.8 мм; измерьте реальные гайки и проверьте посадку. Передний кожух закрепите на этих же шпильках на высоте ${p.sourceZ+16} мм. Установите покупной патрон E10 в кожух, подгоните его крепление. Нить должна оказаться на 16 мм за кожухом, в сторону стены. Размеры конкретного патрона и нити не известны, поэтому посадка — заготовка, а не готовая резьба E10.\n\nИСТОЧНИК\nПрозрачная мини-лампа E10 3.5 V / 0.2 A / 0.7 W, например https://www.batterien-und-akkus.com/kugellampe-e10-3-5v-0-2a . Цена карточки 0.59 EUR без доставки на 28.10.2026. Питание 3.5 V DC с ограничением тока. НЕ 230 V. Эффективный размер нити ${p.emitter} мм — оценка, продавец его не указывает.\n\nРАСЧЁТ\nИспользуются ТЕ ЖЕ треугольники, что в STL, включая втулки, буртики и печатные шайбы; дополнительно трассируются номинальные покупные шпильки M2. Положение деталей после нормализации STL для печати задано в assembly.json. Изображение на стене не накладывается вместо расчёта. Равномерный светящийся диск, ${sim.samples} выборок; относительная освещённость. Центральная область ${d.rootW}x${d.rootH} мм и небольшой запас заняты креплением и исключены из IoU. IoU вне центра: ${(sim.iou*100).toFixed(2)}%. Метрика относится к чёрно-белой цели после порога, а не к цветному исходнику.\n\nОГРАНИЧЕНИЯ\nКонтурная аппроксимация, перемычки и тени стоек изменяют исходник. Полутона и цвета не воспроизводятся. Снимок конструкции не восстанавливается автоматически: приложению нужен рисунок желаемой тени. Стекло колбы, купленный патрон, провода, гайки и шайбы не трассируются; номинальные стержни M2 трассируются. Отражения, дифракция, материал и нагрев не моделируются. Физические, тепловые и прочностные испытания не проводились. Не допускайте контакта колбы с пластиком, проверьте температуру и вентиляцию перед длительной работой.\n`;}
function diagram(){const p=design.p;return `<svg xmlns="http://www.w3.org/2000/svg" width="800" height="380" viewBox="0 0 800 380"><rect width="800" height="380" fill="#182019"/><g font-family="sans-serif" font-size="16" fill="#d4d7be"><path d="M70 40V310" stroke="#b8c5aa" stroke-width="5"/><path d="M70 280H610V180" fill="none" stroke="#849a73" stroke-width="6"/><path d="M290 95V245M308 110V225" stroke="#aebba0" stroke-width="10"/><circle cx="510" cy="168" r="13" fill="#efbd6a"/><path d="M610 110V225" stroke="#aebba0" stroke-width="14"/><path d="M510 168L70 55M510 168L70 297" stroke="#e8b571" stroke-dasharray="7 6" fill="none"/><text x="40" y="345">Стена</text><text x="230" y="70">Фигура + рельеф</text><text x="465" y="100">Нить E10</text><text x="635" y="172">Кожух</text><text x="210" y="340">Стена → фигура: ${p.gap} мм</text><text x="210" y="370">Стена → нить: ${p.sourceZ} мм · рельеф ${p.relief} мм</text></g></svg>`;}
async function exportKit(){if(!sim||!design)return;const d=design;$('export').disabled=true;toast('Сохраняю печатные детали и расчёт…');try{await new Promise(r=>setTimeout(r,20));const png=await new Promise(r=>$('projectionCanvas').toBlob(r,'image/png'));const files=[['shadow-sculpture.stl',stlBuffer(printable(d.sculpture),'ShadowForge wall sculpture mm')],['wall-base-and-posts.stl',stlBuffer(printable(d.support))],['front-cover.stl',stlBuffer(printable(d.cover))],['retaining-washer.stl',stlBuffer(d.washer)],['assembly.json',JSON.stringify({units:'mm',wallZ:0,source:[d.p.sourceX,d.p.sourceY,d.p.sourceZ],parts:[{file:'shadow-sculpture.stl',position:[0,0,d.bounds[2][0]]},{file:'wall-base-and-posts.stl',position:[0,0,0]},{file:'front-cover.stl',position:[0,0,d.p.sourceZ+16]},...d.posts.map(([x,y])=>({file:'retaining-washer.stl',position:[x,y,d.p.gap+d.p.thickness]}))],purchasedRods:d.posts.map(([x,y])=>({type:'M2',position:[x,y,0],diameter:2,length:d.p.sourceZ+24}))},null,2)],['project.json',JSON.stringify(project(),null,2)],['README.txt',instructions()],['setup.svg',diagram()],['wall-shadow.png',await png.arrayBuffer()]];save(zipStore(files),'shadowforge-wall-lamp.zip');toast('Комплект настенного светильника готов.');}catch(e){toast(e.message);}finally{$('export').disabled=false;}}
for(const id of ids)$(id).addEventListener('input',()=>{settings[id]=+$(id).value;output(id);if(id==='exposure'){paintWall();return;}calculate();});$('invert').addEventListener('change',()=>{settings.invert=$('invert').checked;calculate();});$('showBody').addEventListener('change',paintWall);$('explode').addEventListener('change',modelOptions);$('wallVisible').addEventListener('change',modelOptions);
for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>switchView(b.dataset.view));$('reset').addEventListener('click',()=>{settings={...DEFAULTS};sync();calculate();});$('highQuality').addEventListener('click',()=>calculate(320,25));$('export').addEventListener('click',exportKit);$('helpExport').addEventListener('click',exportKit);$('downloadSculpture').addEventListener('click',()=>{if(design)save(new Blob([stlBuffer(printable(design.sculpture))],{type:'model/stl'}),'shadow-sculpture.stl');});$('saveProject').addEventListener('click',()=>save(new Blob([JSON.stringify(project(),null,2)],{type:'application/json'}),'shadowforge-wall-project.json'));
const styleGroup=document.createElement('div');styleGroup.className='segmented';for(const[style,label]of[['solid','Силуэт с деталями'],['lines','Линии']]){const b=document.createElement('button');b.dataset.style=style;b.textContent=label;b.addEventListener('click',()=>{settings.style=style;settings.threshold=style==='solid'?.30:.14;sync();calculate();});styleGroup.appendChild(b);}$('polarity').before(styleGroup);
for(const id of['instructions','helpButton'])$(id).addEventListener('click',()=>$('helpDialog').showModal());$('closeHelp').addEventListener('click',()=>$('helpDialog').close());$('helpDialog').addEventListener('click',e=>{if(e.target===$('helpDialog'))$('helpDialog').close();});
$('imageInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>20e6){toast('Изображение должно быть меньше 20 МБ.');return;}const url=URL.createObjectURL(file);try{await loadImage(url,file.name.replace(/\.[^.]+$/,''));}catch(err){toast(err.message);}finally{URL.revokeObjectURL(url);}e.target.value='';});
$('projectInput').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>15e6)throw new Error('Проект слишком большой.');const data=JSON.parse(await file.text());if(data.format!=='shadowforge-wall'||data.version!==2||!/^data:image\/png;base64,/.test(data.image))throw new Error('Нужен проект настенного светильника версии 2.');const next={...DEFAULTS};for(const id of ids){const v=data.settings?.[id];if(typeof v!=='number'||!Number.isFinite(v)||v<+$(id).min||v>+$(id).max)throw new Error('Некорректный параметр: '+id);next[id]=v;}next.invert=!!data.settings.invert;next.style=['solid','lines'].includes(data.settings.style)?data.settings.style:'solid';settings=next;sync();await loadImage(data.image,String(data.name||'Референс').slice(0,100));toast('Проект открыт.');}catch(err){toast(err.message);}e.target.value='';});
sync();loadImage('assets/batman.png','Batman').catch(e=>fail(e.message));
